  1→import { useState, useRef, useEffect } from 'react';
  2→import ReactMarkdown from 'react-markdown';
  3→import remarkGfm from 'remark-gfm';
  4→import { useTranslation } from '../hooks/useTranslation';
  5→import type { ChatMessage, ContentSegment } from '../types';
  6→import { useAgent } from '../hooks/useAgent';
  7→import { InlineQueryResult } from './InlineQueryResult';
  8→import './MessageBubble.css';
  9→
 10→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
 11→  // Use streaming remainder if available
 12→  if (streamingRemainder?.trim()) {
 13→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
 14→    const last = lines[lines.length - 1] || '';
 15→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
 16→  }
 17→  // Otherwise use last thinking segment's last line
 18→  for (let i = segments.length - 1; i >= 0; i--) {
 19→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
 20→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
 21→      const last = lines[lines.length - 1] || '';
 22→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
 23→    }
 24→  }
 25→  return t('thinking');
 26→}
 27→
 28→function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming }: {
 29→  segments: ContentSegment[];
 30→  streamingRemainder?: string;
 31→  isThinkingPhase: boolean;
 32→  isAgentStreaming: boolean;
 33→}) {
 34→  const { t } = useTranslation();
 35→  // All non-answer segments go inside the thinking block
 36→  const thinkingSegments = segments.filter((s) => s.type !== 'answer');
 37→  const hasContent = thinkingSegments.some(
 38→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult)
 39→  ) || streamingRemainder?.trim();
 40→
 41→  if (!hasContent) return null;
 42→
 43→  // Show preview only while agent is still working (hidden by CSS when collapsible is open anyway)
 44→  const summary = isAgentStreaming ? getLastThinkingLine(segments, streamingRemainder, t) : '';
 45→
 46→  return (
 47→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isThinkingPhase || undefined}>
 48→      <summary className="message-bubble__collapsible-summary">
 49→        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
 50→        {summary && <span className="message-bubble__collapsible-preview">{summary}</span>}
 51→      </summary>
 52→      <div className="message-bubble__thinking-body">
 53→        {thinkingSegments.map((seg, i) => {
 54→          if (seg.type === 'thinking' && seg.text?.trim()) {
 55→            return (
 56→              <div key={i} className="message-bubble__segment-content">
 57→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
 58→              </div>
 59→            );
 60→          }
 61→          if (seg.type === 'tool' && seg.toolResult) {
 62→            return (
 63→              <div key={i} className="message-bubble__tool-segment">
 64→                <InlineQueryResult result={seg.toolResult} />
 65→              </div>
 66→            );
 67→          }
 68→          return null;
 69→        })}
 70→        {streamingRemainder?.trim() && (
 71→          <div className="message-bubble__segment-content">
 72→            <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
 73→          </div>
 74→        )}
 75→      </div>
 76→    </details>
 77→  );
 78→}
