 74→      // If there's pending history from a delete, start a new Langfuse session with that context
 75→      const pendingHistory = pendingHistoryRef.current;
 76→      pendingHistoryRef.current = null;
 77→      const langfuseSessionId = pendingHistory ? crypto.randomUUID() : null;
 78→
 79→      const controller = new AbortController();
 80→      abortRef.current = controller;
 81→
 82→      await runAgentLoop(
 83→        text,
 84→        sessionIdRef.current,
 85→        langfuseSessionId,
 86→        pendingHistory,
 87→        {
 88→          onTextChunk: (chunk) => {
 89→            textBufferRef.current += chunk;
 90→            if (!flushTimerRef.current) {
 91→              flushTimerRef.current = setTimeout(() => {
 92→                flushText();
 93→                flushTimerRef.current = null;
 94→              }, 50);
 95→            }
 96→          },
 97→          onThinkingDone: () => {
 98→            // Extended thinking just ended and a text block is starting.
 99→            // Create a thinking segment from accumulated thinking text.
100→            if (flushTimerRef.current) {
101→              clearTimeout(flushTimerRef.current);
102→              flushTimerRef.current = null;
103→            }
104→            flushText();
105→            if (currentTextRef.current.trim()) {
106→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
107→              currentTextRef.current = '';
108→            }
109→            setMessages((prev) =>
110→              prev.map((m) =>
111→                m.id === assistantId
112→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
113→                  : m
114→              )
115→            );
116→          },
117→          onToolCall: (pending: ToolCallResult) => {
118→            if (flushTimerRef.current) {
119→              clearTimeout(flushTimerRef.current);
120→              flushTimerRef.current = null;
121→            }
122→            flushText();
123→            if (currentTextRef.current.trim()) {
124→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
125→              currentTextRef.current = '';
126→            }
127→            // Add a pending tool segment so the input is shown immediately
128→            segmentsRef.current.push({
129→              type: 'tool',
130→              toolResult: pending,
131→            });
132→            setMessages((prev) =>
133→              prev.map((m) =>
134→                m.id === assistantId
135→                  ? { ...m, segments: [...segmentsRef.current] }
136→                  : m
137→              )
138→            );
139→          },
140→          onToolResult: (result: ToolCallResult) => {
141→            // Merge result into pending tool segment (keep input info, add output)
142→            const pendingIdx = segmentsRef.current.findIndex(
143→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
144→            );
145→            if (pendingIdx !== -1) {
146→              const pending = segmentsRef.current[pendingIdx].toolResult!;
147→              segmentsRef.current[pendingIdx] = {
148→                type: 'tool',
149→                toolResult: {
150→                  ...pending,
151→                  ...result,
152→                  toolName: result.toolName || pending.toolName,
153→                  command: result.command || pending.command,
154→                  toolInput: result.toolInput || pending.toolInput,
155→                },
156→              };
157→            } else {
158→              segmentsRef.current.push({ type: 'tool', toolResult: result });
159→            }
160→            setMessages((prev) =>
161→              prev.map((m) =>
162→                m.id === assistantId
163→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
164→                  : m
165→              )
166→            );
167→            refreshTables();
168→          },
169→          onDone: (newSessionId) => {
170→            if (newSessionId) sessionIdRef.current = newSessionId;
171→            if (flushTimerRef.current) {
172→              clearTimeout(flushTimerRef.current);
173→              flushTimerRef.current = null;
174→            }
175→            flushText();
176→            if (currentTextRef.current.trim()) {
177→              segmentsRef.current.push({
178→                type: 'answer',
179→                text: currentTextRef.current,
180→              });
181→              currentTextRef.current = '';
182→            }
183→            setMessages((prev) =>
184→              prev.map((m) =>
185→                m.id === assistantId
186→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
187→                  : m
188→              )
189→            );
190→            setIsStreaming(false);
191→            abortRef.current = null;
192→          },
193→          onError: (error) => {
194→            if (flushTimerRef.current) {
195→              clearTimeout(flushTimerRef.current);
196→              flushTimerRef.current = null;
197→            }
198→            flushText();
199→            setMessages((prev) =>
200→              prev.map((m) =>
201→                m.id === assistantId
202→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
203→                  : m
204→              )
205→            );
206→            setIsStreaming(false);
207→            abortRef.current = null;
208→          },
209→        },
210→        controller.signal,
211→        userSessionId,
212→      );
213→    },
214→    [isStreaming, flushText, refreshTables, userSessionId]
215→  );
216→
217→  const editMessage = useCallback(
218→    async (messageIndex: number, newContent: string) => {
219→      if (isStreaming) return;
220→
221→      // Build conversation history from messages before the edit point
222→      const conversationHistory: { role: string; content: string }[] = [];
223→      for (let i = 0; i < messageIndex; i++) {
224→        const msg = messages[i];
225→        if (msg.role === 'user' || msg.role === 'assistant') {
226→          conversationHistory.push({ role: msg.role, content: msg.content });
227→        }
228→      }
229→
230→      const assistantId = generateId();
231→      assistantIdRef.current = assistantId;
232→
233→      const userMsg: ChatMessage = {
234→        id: generateId(),
235→        role: 'user',
236→        content: newContent,
237→      };
238→      const assistantMsg: ChatMessage = {
239→        id: assistantId,
240→        role: 'assistant',
241→        content: '',
242→        toolCalls: [],
243→        isStreaming: true,
244→      };
245→
246→      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
247→      setIsStreaming(true);
248→      textBufferRef.current = '';
249→      segmentsRef.current = [];
250→      currentTextRef.current = '';
251→
252→      const controller = new AbortController();
253→      abortRef.current = controller;
254→
255→      await runAgentEditLoop(
256→        newContent,
257→        conversationHistory,
258→        crypto.randomUUID(),
259→        {
260→          onTextChunk: (chunk) => {
261→            textBufferRef.current += chunk;
262→            if (!flushTimerRef.current) {
263→              flushTimerRef.current = setTimeout(() => {
264→                flushText();
265→                flushTimerRef.current = null;
266→              }, 50);
267→            }
268→          },
269→          onThinkingDone: () => {
270→            if (flushTimerRef.current) {
271→              clearTimeout(flushTimerRef.current);
272→              flushTimerRef.current = null;
273→            }
274→            flushText();
275→            if (currentTextRef.current.trim()) {
276→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
277→              currentTextRef.current = '';
278→            }
279→            setMessages((prev) =>
280→              prev.map((m) =>
281→                m.id === assistantId
282→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
283→                  : m
284→              )
285→            );
286→          },
287→          onToolCall: (pending: ToolCallResult) => {
288→            if (flushTimerRef.current) {
289→              clearTimeout(flushTimerRef.current);
290→              flushTimerRef.current = null;
291→            }
292→            flushText();
293→            if (currentTextRef.current.trim()) {
294→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
295→              currentTextRef.current = '';
296→            }
297→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
298→            setMessages((prev) =>
299→              prev.map((m) =>
300→                m.id === assistantId
301→                  ? { ...m, segments: [...segmentsRef.current] }
302→                  : m
303→              )
304→            );
305→          },
306→          onToolResult: (result: ToolCallResult) => {
307→            const pendingIdx = segmentsRef.current.findIndex(
308→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
309→            );
310→            if (pendingIdx !== -1) {
311→              const pending = segmentsRef.current[pendingIdx].toolResult!;
312→              segmentsRef.current[pendingIdx] = {
313→                type: 'tool',
314→                toolResult: {
315→                  ...pending,
316→                  ...result,
317→                  toolName: result.toolName || pending.toolName,
318→                  command: result.command || pending.command,
319→                  toolInput: result.toolInput || pending.toolInput,
320→                },
321→              };
322→            } else {
323→              segmentsRef.current.push({ type: 'tool', toolResult: result });
324→            }
325→            setMessages((prev) =>
326→              prev.map((m) =>
327→                m.id === assistantId
328→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
329→                  : m
330→              )
331→            );
332→            refreshTables();
333→          },
334→          onDone: (newSessionId) => {
335→            if (newSessionId) sessionIdRef.current = newSessionId;
336→            if (flushTimerRef.current) {
337→              clearTimeout(flushTimerRef.current);
338→              flushTimerRef.current = null;
339→            }
340→            flushText();
341→            if (currentTextRef.current.trim()) {
342→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
343→              currentTextRef.current = '';
344→            }
345→            setMessages((prev) =>
346→              prev.map((m) =>
347→                m.id === assistantId
348→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
349→                  : m
350→              )
351→            );
352→            setIsStreaming(false);
353→            abortRef.current = null;
354→          },
355→          onError: (error) => {
356→            if (flushTimerRef.current) {
357→              clearTimeout(flushTimerRef.current);
358→              flushTimerRef.current = null;
359→            }
360→            flushText();
361→            setMessages((prev) =>
362→              prev.map((m) =>
363→                m.id === assistantId
364→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
365→                  : m
366→              )
367→            );
368→            setIsStreaming(false);
369→            abortRef.current = null;
370→          },
371→        },
372→        controller.signal,
373→        userSessionId,
374→      );
375→    },
376→    [isStreaming, messages, flushText, refreshTables, userSessionId]
377→  );
378→
379→  const deleteMessage = useCallback(
380→    (messageIndex: number) => {
381→      if (isStreaming) return;
382→
383→      // Store remaining messages as history for Langfuse context on next send
384→      setMessages((prev) => {
385→        const remaining = prev.slice(0, messageIndex);
386→        pendingHistoryRef.current = remaining
387→          .filter((m) => m.role === 'user' || m.role === 'assistant')
388→          .map((m) => ({ role: m.role, content: m.content }));
389→        return remaining;
390→      });
391→
392→      // Clear session so next message starts fresh
393→      sessionIdRef.current = null;
394→    },
395→    [isStreaming]
396→  );
397→
398→  const clearMessages = useCallback(() => {
399→    if (abortRef.current) {
400→      abortRef.current.abort();
401→    }
402→    setMessages([]);
403→    setIsStreaming(false);
404→    sessionIdRef.current = null;
405→    pendingHistoryRef.current = null;
406→  }, []);
407→
408→  return (
409→    <AgentContext.Provider
410→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages }}
411→    >
412→      {children}
413→    </AgentContext.Provider>
414→  );
415→}
